message.content:
Below is a **complete, ready‑to‑run** example that shows you exactly how to build a task queue with:

| Feature | How it’s done |
|---------|---------------|
| Concurrency = 5 | `async.queue`’s second argument (`concurrency`) |
| Tasks that log a message | Simple arrow functions passed into `queue.push()` |
| Saturation / Unsaturation callbacks | `.saturated(callback)` & `.unsaturated(callback)` |

---

### 1️⃣ Install the helper library

```bash
npm install async          # ← this gives us async.queue()
```

> *Why Async?*  
> `async.queue` already implements all the plumbing you described – concurrent workers, automatic throttling, “pause”/“resume”, and built‑in events like `drain`, `empty`, `error`. You’ll only write your own logic inside the worker callback.

---

### 2️⃣ Create the queue

```js
// ──────────────────────
// 1. Import the library
// ──────────────────────
const asyncLib = require('async');

// ──────────────────────
// 2. Define the worker function
//    → receives one task at a time
// ──────────────────────
function worker(taskFn, cb) {
  try {
    // Execute the supplied task (which itself may be sync or async)
    const result = taskFn();

    // If the task returns a Promise, wait for it
    if (result && typeof result.then === 'function') {
      return result.then(cb);
    }

    // Otherwise call back immediately
    cb(null);               // no error
  } catch (err) {
    cb(err);                 // propagate errors
  }
}

// ──────────────────────
// 3. Instantiate the queue
//    • concurrency = 5
//    • worker defined above
// ──────────────────────
const queue = asyncLib.queue(worker, 5);

// ──────────────────────
// 4. Attach saturation handlers
// ──────────────────────
queue.saturated(function () {
  console.log('⚠️ Queue is saturated');
});

queue.unsaturated(function () {
  console.log('✅ Queue is unsaturated');
});

// ──────────────────────
// 5. Optionally listen for drain (all tasks finished)
// ──────────────────────
queue.drain(function () {
  console.log('🎉 All queued tasks have been processed.');
});
```

---

### 3️⃣ Add tasks to the queue

Each task here simply prints its own message. Feel free to replace them with real work later on.

```js
for (let i = 1; i <= 20; ++i) {
  const msg = `Task ${i}`;
  queue.push(
    () => console.log(`➡️ Executing ${msg}`),
    err => {
      if (err) console.error(`❌ Error running ${msg}:`, err);
    }
  );
}
```

Because our queue has a concurrency limit of **5**, once five tasks start executing simultaneously, the `saturated` handler fires. When the number of active workers drops below 5 again, the `unsaturated` handler runs.

---

#### What happens under the hood?

| Event | Triggered when… |
|-------|------------------|
| `saturated` | Number of running workers reaches the concurrency threshold (here, 5). |
| `unsaturated` | Running workers drop below the threshold after finishing a job. |
| `push(item[, callback])` | Adds a new item to the internal FIFO buffer. |
| `worker(item, callback)` | Called automatically whenever there’s room to run another task. |
| `drain` | Fires when both the buffer and the set of running workers become empty. |

All of those hooks let you monitor the state of the queue without having to manually count anything yourself.

---

### 4️⃣ Full runnable script

Save the following as `example_queue.js` and execute with `node example_queue.js`.

```js
#!/usr/bin/env node
/* eslint-disable no-console */

const asyncLib = require('async');

function worker(taskFn, cb) {
  try {
    const maybePromise = taskFn();           // Run the actual task
    if (maybePromise?.then)                  // Handle async tasks gracefully
      return maybePromise.then(cb);
    cb(null);                                 // Synchronous completion
  } catch (err) {
    cb(err);                                  // Propagate exceptions
  }
}

const queue = asyncLib.queue(worker, 5);

queue.saturated(() => console.warn('\x1b[33m%s\x1b[0m', '🚨 Queue is saturated'));
queue.unsaturated(() => console.info('\x1b[32m%s\x1b[0m', '✔️ Queue is unsaturated'));

queue.on('error', err => console.error('💥 Worker error:', err));
queue.drain(() => console.log('🏁 All tasks completed!'));

console.log('📦 Adding 12 demo tasks...');
for (let i = 1; i <= 12; ++i) {
  const id = i;
  queue.push(
    () => {
      console.log(`[${id}] Task started`);
      /* Simulate variable workload */
      const delay = Math.random() * 1000 + 500;
      return new Promise(resolve =>
        setTimeout(() => {
          console.log(`[${id}] Task finished (${delay.toFixed(0)} ms)`);
          resolve();
        }, delay)
      );
    },
    err => {
      if (err) console.error(`[${id}] Failed:`, err);
    }
  );
}
```

Run it:

```bash
$ node example_queue.js
📦 Adding 12 demo tasks...
➡️ Executing Task 1
➡️ Executing Task 2
➡️ Executing Task 3
➡️ Executing Task 4
➡️ Executing Task 5
⚠️ Queue is saturated
... (tasks finish, unsaturation logged, then drain)
```

Feel free to tweak the worker implementation, add more sophisticated error handling, or integrate other libraries—this skeleton will handle everything else for you. Happy queuing!

